-- Update only exact development-sample sentences superseded by authentication.
-- Official content, other blocks and user-edited text are preserved.
UPDATE admission_pages SET content=(SELECT jsonb_agg(CASE WHEN block->>'type'='paragraph' AND block->>'text' IN ('Online submission will open after secure applicant accounts are available. This development site does not accept applications or documents yet.','Not yet. The application planner lets you choose a program and intake. Secure accounts and submission will be introduced in the authentication phase.') THEN jsonb_set(block,'{text}',to_jsonb(CASE block->>'text' WHEN 'Online submission will open after secure applicant accounts are available. This development site does not accept applications or documents yet.' THEN 'Create a student account, verify your email, then save and submit your application during an open intake. Private document upload is not configured yet.' WHEN 'Not yet. The application planner lets you choose a program and intake. Secure accounts and submission will be introduced in the authentication phase.' THEN 'Yes. Create a student account, verify your email, choose a program and open intake, then save, review and submit your application. Private document upload is not configured yet.' ELSE block->>'text' END)) ELSE block END ORDER BY ord) FROM jsonb_array_elements(content) WITH ORDINALITY AS x(block,ord)),updated_at=now() WHERE is_sample=true AND slug IN ('overview','faq') AND EXISTS(SELECT 1 FROM jsonb_array_elements(content) AS b WHERE b->>'text' IN ('Online submission will open after secure applicant accounts are available. This development site does not accept applications or documents yet.','Not yet. The application planner lets you choose a program and intake. Secure accounts and submission will be introduced in the authentication phase.'));
--> statement-breakpoint
UPDATE announcements SET content=(SELECT jsonb_agg(CASE WHEN block->>'type'='paragraph' AND block->>'text' IN ('Review your program requirements and prepare questions for admissions. Online application submission is not available yet.') THEN jsonb_set(block,'{text}',to_jsonb(CASE block->>'text' WHEN 'Review your program requirements and prepare questions for admissions. Online application submission is not available yet.' THEN 'Review your program requirements, create a student account and verify your email before submitting during an open intake.' ELSE block->>'text' END)) ELSE block END ORDER BY ord) FROM jsonb_array_elements(content) WITH ORDINALITY AS x(block,ord)),updated_at=now() WHERE is_sample=true AND slug IN ('sample-admissions-planning') AND EXISTS(SELECT 1 FROM jsonb_array_elements(content) AS b WHERE b->>'text' IN ('Review your program requirements and prepare questions for admissions. Online application submission is not available yet.'));
